        try:
            cid = int(request.POST['creator_id'])
            creator = User.objects.get(user_id=cid)
            rid = int(request.POST['receiver_id'])
            receiver = User.objects.get(user_id=rid)
            msg = request.POST['message']
            red = int(request.POST['read'])
